INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l81',2,11,81,'A Day at the Museum','博物馆的一天','KS9/33/57 介词综合(教材 L81 Key structures,方案B换情节包):at(时间点/地点一点:at ten o''clock / at the door / at noon)、in(在…里面/穿着:in the city center / in a uniform / in the afternoon)、to(方向:go to / return to)、with(伴随/工具/方式:with our tickets / with great care / with surprising speed)、into(进入:led us into / walked into)','周六,我们去了市中心的科学博物馆。我们十点到达,拿着票在门口等候。一位穿蓝色制服的讲解员把我们带进了第一个大厅。她非常小心地给我们展示了各种旧机器的模型。在一个房间里,一个机器人以惊人的速度移动着。我们站在前面,惊讶地看着它。中午,我们坐在咖啡馆里,聊着看到的东西。下午,我们兴奋地走进了太空展区。我们在博物馆一直待到五点闭馆。在回家的路上,我们商量着要和朋友们再来一次。','{"q":"Listen and answer — Where did they go on Saturday?","options":["To the science museum in the city center","To a soccer game","To the beach","To a movie theater"],"answer_index":0}'::jsonb,'{"title":"KS9/33/57 介词综合 at / in / to / with / into","intro":"常用介词各有分工:①at——具体时间点或一个“点”状的地点(at ten o''clock / at the door / at noon);②in——在某个空间“里面”或“穿着”(in the city center / in a blue uniform / in the afternoon);③to——朝某处“去、到”的方向(go to / return to);④with——“带着、用、以某种方式”(with our tickets / with great care / with surprising speed);⑤into——从外“进入”里面(led us into the hall / walked into the section)。","table":{"headers":["介词","用法与例子"],"rows":[["at","at ten o''clock / at the door / at noon"],["in","in the city center / in a uniform / in the afternoon"],["to","went to the museum / returned to the entrance"],["with","with our tickets / with great care / with speed"],["into","led us into the hall / walked into the section"]]},"specialRules":[{"rule":"美语里“电梯”说 elevator(英式 lift)、“市中心”说 downtown(英式 city centre)、“洗手间”说 restroom(英式 toilet);本课已按美语写。","mark":"elevator/downtown"},{"rule":"in 表“在里面/静止的位置”,into 表“从外到里的动作”:be in the hall(在大厅里)vs walk into the hall(走进大厅)。别混。","mark":"in vs into"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l81',1,NULL,'On Saturday we went to the science museum in the city center. We arrived at ten o''clock and waited at the door with our tickets.','周六,我们去了市中心的科学博物馆。我们十点到达,拿着票在门口等候。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l81',2,NULL,'A guide in a blue uniform led us into the first hall. With great care, she showed us models of old machines.','一位穿蓝色制服的讲解员把我们带进了第一个大厅。她非常小心地给我们展示了各种旧机器的模型。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l81',3,NULL,'In one room, a robot moved with surprising speed. We stood at the front and looked at it with amazement.','在一个房间里,一个机器人以惊人的速度移动着。我们站在前面,惊讶地看着它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l81',4,NULL,'At noon we sat in the café and talked about what we had seen. In the afternoon we walked into the space section with excitement.','中午,我们坐在咖啡馆里,聊着看到的东西。下午,我们兴奋地走进了太空展区。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l81',5,NULL,'We stayed at the museum until it closed at five. On the way home, we talked about coming back with our friends.','我们在博物馆一直待到五点闭馆。在回家的路上,我们商量着要和朋友们再来一次。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
