INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l81','with great care','',NULL,'/wɪð ɡreɪt ker/','She showed us the models with great care.','她非常小心地给我们看模型。','Handle the old book with great care.','非常小心地拿那本旧书。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l81','look at sth with amazement','',NULL,'/lʊk æt wɪð əˈmeɪzmənt/','We looked at the robot with amazement.','我们惊讶地看着那个机器人。','The children looked at the fireworks with amazement.','孩子们惊讶地看着烟花。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l81','talk about','',NULL,'/tɔːk əˈbaʊt/','We talked about what we had seen.','我们聊着看到的东西。','Let''s talk about the plan tomorrow.','咱们明天再谈这个计划。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l81','on the way home','',NULL,'/ɑːn ðə weɪ hoʊm/','On the way home, we talked about coming back.','回家的路上,我们商量着再来一次。','I bought some fruit on the way home.','回家路上我买了些水果。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp1','choice','{"stem":"\"We arrived ___ ten o''clock.\"(在几点钟,用哪个介词)","options":["on","to","at","in"],"answer_index":2,"stem_cn":"我们十点到达。","explanation_cn":"具体的钟点前用 at。✓ We arrived at ten o''clock. ✗ in:用于较长的时间段(in the morning);✗ on:用于星期/日期;✗ to:表方向。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp1','choice','{"stem":"\"We waited ___ the door with our tickets.\"(在门口这个“点”,用哪个介词)","options":["at","into","in","to"],"answer_index":0,"stem_cn":"我们拿着票在门口等候。","explanation_cn":"“在门口”这个“点”状地点用 at。✓ We waited at the door. ✗ in:表“在里面”;✗ into:表“进入”的动作;✗ to:表方向。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp1','choice','{"stem":"\"___ noon we sat in the café.\"(在中午,用哪个介词)","options":["On","In","To","At"],"answer_index":3,"stem_cn":"中午我们坐在咖啡馆里。","explanation_cn":"“在中午(noon)”用 at。✓ At noon we sat in the café. ✗ In:noon 是时间点,不用 in;✗ On:用于星期/日期;✗ To:表方向。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp2','choice','{"stem":"\"We went to the science museum ___ the city center.\"(在市中心里面,用哪个介词)","options":["to","on","in","at"],"answer_index":2,"stem_cn":"我们去了市中心的科学博物馆。","explanation_cn":"“在市中心里面”用 in。✓ the museum in the city center. ✗ at:多用于小地点/一点;✗ on:表“在…上面”;✗ to:表方向。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp2','choice','{"stem":"\"A guide ___ a blue uniform showed us around.\"(表“穿着”,用哪个介词)","options":["in","with","on","at"],"answer_index":0,"stem_cn":"一位穿蓝色制服的讲解员带我们参观。","explanation_cn":"“穿着(某衣服)”用 in。✓ a guide in a blue uniform. ✗ on:不这样表“穿着整身衣服”;✗ with:表“带着”;✗ at:表地点/时间点。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp2','choice','{"stem":"\"___ the afternoon we visited the space section.\"(在下午,用哪个介词)","options":["On","In","To","At"],"answer_index":1,"stem_cn":"下午我们参观了太空展区。","explanation_cn":"“在下午”用 in the afternoon。✓ In the afternoon we visited the space section. ✗ At:多用于具体钟点/noon;✗ On:用于星期/日期;✗ To:表方向。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp3','choice','{"stem":"\"On Saturday we went ___ the science museum.\"(去某地、表方向,用哪个介词)","options":["into","at","in","to"],"answer_index":3,"stem_cn":"周六我们去了科学博物馆。","explanation_cn":"“去某地、表方向”用 to。✓ we went to the science museum. ✗ at:表“在某处”;✗ in:表“在里面”;✗ into:表“进入”的动作,go 常与 to 搭配。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp3','choice','{"stem":"\"We took the elevator ___ the top floor.\"(到某层,用哪个介词)","options":["to","at","in","into"],"answer_index":0,"stem_cn":"我们坐电梯到顶楼。","explanation_cn":"“(乘电梯)到某层”用 to。✓ We took the elevator to the top floor. ✗ at:表“在”;✗ in:表“里面”;✗ into:此处表方向用 to。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp3','choice','{"stem":"\"After lunch we returned ___ the entrance.\"(回到某处,用哪个介词)","options":["into","in","to","at"],"answer_index":2,"stem_cn":"午饭后我们回到了入口。","explanation_cn":"“回到某处”用 return to。✓ we returned to the entrance. ✗ at / in / into:return 后接目的地用 to。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp4','choice','{"stem":"\"We waited at the door ___ our tickets.\"(表“带着”,用哪个介词)","options":["with","in","at","by"],"answer_index":0,"stem_cn":"我们拿着票在门口等候。","explanation_cn":"“带着(票)”用 with。✓ We waited at the door with our tickets. ✗ by:表“乘、靠”;✗ at:表地点;✗ in:表“里面”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp4','choice','{"stem":"\"She showed us the models ___ great care.\"(表“以…方式、非常小心地”,用哪个介词)","options":["by","with","at","in"],"answer_index":1,"stem_cn":"她非常小心地给我们看模型。","explanation_cn":"“以…方式、非常小心地”用 with(with great care)。✓ She showed us the models with great care. ✗ in:此处不合;✗ by:表方式时接手段(by bus);✗ at:表地点/时间点。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp4','choice','{"stem":"\"A robot moved ___ surprising speed.\"(以某种速度,用哪个介词)","options":["by","in","with","at"],"answer_index":2,"stem_cn":"一个机器人以惊人的速度移动。","explanation_cn":"“以某种速度”用 with(with surprising speed)。✓ A robot moved with surprising speed. ✗ in:不合;✗ by:不这样表速度;✗ at:此处用 with。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp5','choice','{"stem":"\"A guide led us ___ the first hall.\"(表“进入(某空间)”,用哪个介词)","options":["of","into","on","at"],"answer_index":1,"stem_cn":"一位讲解员把我们带进了第一个大厅。","explanation_cn":"“从外进入(某空间)”的动作用 into。✓ A guide led us into the first hall. ✗ at:表“在一点”;✗ on:表“在上面”;✗ of:表所属。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp5','choice','{"stem":"\"In the afternoon we walked ___ the space section.\"(表“走进(某区域)”,用哪个介词)","options":["into","on","at","to"],"answer_index":0,"stem_cn":"下午我们走进了太空展区。","explanation_cn":"“走进(某区域)”的动作用 into。✓ we walked into the space section. ✗ at:表“在”;✗ on:表“在上面”;✗ to:walk into 是固定“走进里面”。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp5','choice','{"stem":"\"We sat in the café and talked ___ what we had seen.\"(表“谈论(某事)”,用哪个介词)","options":["into","at","about","with"],"answer_index":2,"stem_cn":"我们坐在咖啡馆里,聊着看到的东西。","explanation_cn":"“谈论(某事)”用 talk about。✓ talked about what we had seen. ✗ at:不这样搭配;✗ into:表“进入”;✗ with:talk with 是“和某人谈”,后接“谈的内容”要用 about。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp6','choice','{"stem":"\"A ___ in a blue uniform showed us around.\"(讲解员、导游用哪个词)","options":["driver","guide","doctor","guest"],"answer_index":1,"stem_cn":"一位穿蓝制服的讲解员带我们参观。","explanation_cn":"带人参观、讲解的人是 guide(讲解员、导游)。✓ A guide in a blue uniform showed us around. ✗ guest:是“客人”;✗ driver:是“司机”;✗ doctor:是“医生”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp6','choice','{"stem":"\"In the afternoon we walked into the space ___.\"(展区、部分用哪个词)","options":["uniform","model","ticket","section"],"answer_index":3,"stem_cn":"下午我们走进了太空展区。","explanation_cn":"展馆里的“展区、部分”是 section。✓ the space section. ✗ ticket:是“票”;✗ uniform:是“制服”;✗ model:是“模型”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',5,'am2_l81_gp6','choice','{"stem":"\"We looked at the robot with ___.\"(惊讶用哪个词)","options":["boredom","fear","amazement","anger"],"answer_index":2,"stem_cn":"我们惊讶地看着那个机器人。","explanation_cn":"“惊讶、惊奇”用 amazement。✓ looked at it with amazement. ✗ boredom:是“无聊”;✗ anger:是“愤怒”;✗ fear:是“恐惧”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',6,NULL,'choice','{"stem":"美语里\"电梯\"常说:","options":["lift","rising-room","elevator","up-box"],"answer_index":2,"explanation_cn":"美语“电梯”说 elevator;英式说 lift。✓ Take the elevator to the third floor. 坐电梯到三楼。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',6,NULL,'choice','{"stem":"美语里\"市中心\"常说:","options":["town-middle","central-city","city centre","downtown"],"answer_index":3,"explanation_cn":"美语“市中心”说 downtown;英式说 city centre。✓ The museum is downtown. 博物馆在市中心。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',6,NULL,'choice','{"stem":"museum 的意思是:","options":["博物馆","剧院","图书馆","车站"],"answer_index":0,"explanation_cn":"museum = 博物馆。✓ the science museum 科学博物馆。\n顺带记:图书馆 = library;剧院 = theater;车站 = station."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',6,NULL,'choice','{"stem":"guide 的意思是:","options":["医生","讲解员,导游","老师","司机"],"answer_index":1,"explanation_cn":"guide = 讲解员、导游。✓ A guide in a blue uniform 一位穿蓝制服的讲解员。\n顺带记:司机 = driver;医生 = doctor;老师 = teacher."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',6,NULL,'choice','{"stem":"uniform 的意思是:","options":["手套","鞋子","制服","帽子"],"answer_index":2,"explanation_cn":"uniform = 制服。✓ a blue uniform 蓝色制服。\n顺带记:帽子 = hat;手套 = gloves;鞋子 = shoes."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',6,NULL,'choice','{"stem":"amazement 的意思是:","options":["惊讶,惊奇","疲惫","愤怒","无聊"],"answer_index":0,"explanation_cn":"amazement = 惊讶、惊奇。✓ with amazement 惊讶地。\n顺带记:无聊 = boredom;愤怒 = anger;疲惫 = tiredness."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',7,NULL,'cloze','{"stem":"第 1 空","context":"On Saturday we went ___1___ the science museum ___2___ the city center. A guide ___3___ a blue uniform led us into the first hall. We looked at the robots ___4___ great amazement.","blank_no":1,"options":["to","at","in","into"],"answer_index":0,"explanation_cn":"“去某地、表方向”用 to。✓ we went to the science museum.\n✗ at:表“在某处”;✗ in:表“在里面”;✗ into:go 常与 to 搭配。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',7,NULL,'cloze','{"stem":"第 2 空","context":"On Saturday we went ___1___ the science museum ___2___ the city center. A guide ___3___ a blue uniform led us into the first hall. We looked at the robots ___4___ great amazement.","blank_no":2,"options":["in","at","to","on"],"answer_index":0,"explanation_cn":"“在市中心里面”用 in。✓ the museum in the city center.\n✗ at:多用于一点;✗ to:表方向;✗ on:表“在上面”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',7,NULL,'cloze','{"stem":"第 3 空","context":"On Saturday we went ___1___ the science museum ___2___ the city center. A guide ___3___ a blue uniform led us into the first hall. We looked at the robots ___4___ great amazement.","blank_no":3,"options":["in","with","at","on"],"answer_index":0,"explanation_cn":"“穿着(制服)”用 in。✓ a guide in a blue uniform.\n✗ with:表“带着”;✗ at:表地点;✗ on:不这样表整身穿着。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',7,NULL,'cloze','{"stem":"第 4 空","context":"On Saturday we went ___1___ the science museum ___2___ the city center. A guide ___3___ a blue uniform led us into the first hall. We looked at the robots ___4___ great amazement.","blank_no":4,"options":["with","by","at","in"],"answer_index":0,"explanation_cn":"“以…方式(惊讶地)”用 with。✓ We looked at the robots with great amazement.\n✗ by:不合;✗ at:表地点/时间点;✗ in:此处用 with。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',8,NULL,'choice','{"stem":"Where did they go on Saturday?","options":["To the science museum in the city center","To the beach","To a concert","To a soccer field"],"answer_index":0,"explanation_cn":"课文说 On Saturday we went to the science museum in the city center。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',8,NULL,'choice','{"stem":"Who led them into the first hall?","options":["A robot","The museum director","A guide in a blue uniform","A police officer"],"answer_index":2,"explanation_cn":"课文说 A guide in a blue uniform led us into the first hall。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',8,NULL,'choice','{"stem":"How long did they stay at the museum?","options":["For only ten minutes","Until it closed at five","Until noon","All night"],"answer_index":1,"explanation_cn":"课文说 We stayed at the museum until it closed at five。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',9,NULL,'choice','{"stem":"你想说\"我们十点在门口等着\"(at 表钟点和“点”状地点):","options":["We waited at the door at ten o''clock.","We waited to the door to ten o''clock.","We waited on the door on ten o''clock.","We waited in the door in ten o''clock."],"answer_index":0,"explanation_cn":"“在门口(点状地点)”和“在几点钟”都用 at。✓ We waited at the door at ten o''clock. 场合:说“在某个点、某个钟点”做某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',9,NULL,'choice','{"stem":"你想说\"一位讲解员把我们带进了大厅\"(into 表“从外进入里面”):","options":["A guide led us at the hall.","A guide led us on the hall.","A guide led us with the hall.","A guide led us into the hall."],"answer_index":3,"explanation_cn":"“从外进入里面”的动作用 into。✓ A guide led us into the hall. 场合:说“带某人走进某处”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',9,NULL,'choice','{"stem":"你想说\"我们惊讶地看着那个机器人\"(with amazement 表方式):","options":["We looked at the robot at amazement.","We looked at the robot of amazement.","We looked at the robot with amazement.","We looked at the robot in amazement by."],"answer_index":2,"explanation_cn":"“以…情绪/方式”用 with(with amazement)。✓ We looked at the robot with amazement. 场合:说“带着某种情绪去做”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"museum 的意思是:","options":["博物馆","车站","图书馆","剧院"],"answer_index":0,"explanation_cn":"museum = 博物馆。✓ the science museum 科学博物馆。\n顺带记:图书馆 = library;剧院 = theater;车站 = station."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"amazement 的意思是:","options":["疲惫","愤怒","惊讶,惊奇","无聊"],"answer_index":2,"explanation_cn":"amazement = 惊讶、惊奇。✓ with amazement 惊讶地。\n顺带记:无聊 = boredom;愤怒 = anger;疲惫 = tiredness."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"\"We arrived ___ ten o''clock.\"(在几点钟,用哪个介词)","options":["at","in","on","to"],"answer_index":0,"stem_cn":"我们十点到达。","explanation_cn":"具体钟点前用 at。✓ We arrived at ten o''clock.\n✗ in:用于较长时段;✗ on:用于星期/日期;✗ to:表方向。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"\"A guide led us ___ the hall.\"(表“进入里面”,用哪个介词)","options":["at","into","on","of"],"answer_index":1,"stem_cn":"一位讲解员把我们带进了大厅。","explanation_cn":"“从外进入里面”的动作用 into。✓ A guide led us into the hall.\n✗ at:表“在一点”;✗ on:表“在上面”;✗ of:表所属。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"\"with great care\" 的意思是:","options":["毫不在意地","很大声地","很快地","非常小心地"],"answer_index":3,"explanation_cn":"with great care = 非常小心地。如 She showed us the models with great care。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"\"talk about\" 的意思是:","options":["沉默不语","谈论、议论","大声争吵","走开"],"answer_index":1,"explanation_cn":"talk about = 谈论、议论(某事)。如 We talked about what we had seen。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"What did they do at noon?","options":["They took a nap on a bench","They watched a movie","They sat in the café and talked about what they had seen","They went home"],"answer_index":2,"passage":"On Saturday we went to the science museum in the city center. We arrived at ten o''clock and waited at the door with our tickets. A guide in a blue uniform led us into the first hall. With great care, she showed us models of old machines. In one room, a robot moved with surprising speed. We stood at the front and looked at it with amazement. At noon we sat in the café and talked about what we had seen. In the afternoon we walked into the space section with excitement. We stayed at the museum until it closed at five. On the way home, we talked about coming back with our friends.","explanation_cn":"课文说 At noon we sat in the café and talked about what we had seen。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"How did the robot move?","options":["With surprising speed","It moved backward only","Very slowly","It did not move at all"],"answer_index":0,"passage":"On Saturday we went to the science museum in the city center. We arrived at ten o''clock and waited at the door with our tickets. A guide in a blue uniform led us into the first hall. With great care, she showed us models of old machines. In one room, a robot moved with surprising speed. We stood at the front and looked at it with amazement. At noon we sat in the café and talked about what we had seen. In the afternoon we walked into the space section with excitement. We stayed at the museum until it closed at five. On the way home, we talked about coming back with our friends.","explanation_cn":"课文说 a robot moved with surprising speed。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"What was the guide wearing?","options":["A white coat","A red hat","A blue uniform","Ordinary clothes"],"answer_index":2,"audio":"On Saturday we went to the science museum in the city center. We arrived at ten o''clock and waited at the door with our tickets. A guide in a blue uniform led us into the first hall. With great care, she showed us models of old machines. In one room, a robot moved with surprising speed. We stood at the front and looked at it with amazement. At noon we sat in the café and talked about what we had seen. In the afternoon we walked into the space section with excitement. We stayed at the museum until it closed at five. On the way home, we talked about coming back with our friends.","explanation_cn":"课文说 A guide in a blue uniform led us into the first hall。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l81',10,NULL,'choice','{"stem":"What did they plan on the way home?","options":["To come back with their friends","To buy a robot","To never return","To move to the city"],"answer_index":0,"audio":"On Saturday we went to the science museum in the city center. We arrived at ten o''clock and waited at the door with our tickets. A guide in a blue uniform led us into the first hall. With great care, she showed us models of old machines. In one room, a robot moved with surprising speed. We stood at the front and looked at it with amazement. At noon we sat in the café and talked about what we had seen. In the afternoon we walked into the space section with excitement. We stayed at the museum until it closed at five. On the way home, we talked about coming back with our friends.","explanation_cn":"课文说 On the way home, we talked about coming back with our friends。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l82',2,11,82,'The Thing in the Attic','阁楼里的东西','KS10/34/58 被动语态各时态(教材 L82 Key structures,方案B换情节包):一般过去被动(was found/was covered/was cleaned)、现在进行被动(is being examined)、现在完成被动(have been seen)、过去完成被动(had been forgotten)、一般现在被动(is kept/is checked)、将来被动(will be shown);辅以易混词 laugh vs laugh at、wash vs wash up','上周,在一座老房子的阁楼里发现了一件古怪的旧物。它落满灰尘,已被遗忘了一百多年。起初,一家人还嘲笑它,以为是废物。可当把它清理干净后,底下露出一个奇特的图案。如今,这件物品正由城里博物馆的专家们鉴定。“这样的东西以前只被见过几次,”一位专家说。“得先仔细研究,才能说清它是什么。”每一件珍贵的物品都被保存在一个专门的房间里,每天都有人检查。下个月,这件神秘的物品将第一次向公众展出。那家曾经嘲笑它的人,如今为它将在博物馆展出而感到自豪。','{"q":"Listen and answer — Where was the strange object found?","options":["In the attic of an old house","At the bottom of the sea","In a busy market","On a mountain top"],"answer_index":0}'::jsonb,'{"title":"KS10/34/58 被动语态各时态","intro":"被动语态 = be + 过去分词,“被…”的意思;时态的变化体现在 be 上:①一般过去 was/were done(was found 被发现);②现在进行 is/are being done(is being examined 正在被鉴定);③现在完成 have/has been done(have been seen 被见过);④过去完成 had been done(had been forgotten 曾被遗忘);⑤一般现在 is/are done(is kept 被保存);⑥将来 will be done(will be shown 将被展出)。SD:laugh(笑)vs laugh at(嘲笑);wash(洗)vs wash up(洗餐具/冲上岸)。","table":{"headers":["时态","被动形式与例子"],"rows":[["一般过去","was found / was cleaned"],["现在进行","is being examined"],["现在完成 / 过去完成","have been seen / had been forgotten"],["一般现在 / 将来","is kept / will be shown"],["易混词","laugh at(嘲笑) / wash up(洗餐具)"]]},"specialRules":[{"rule":"美语里“垃圾”说 trash(英式 rubbish)、“手电筒”说 flashlight(英式 torch)、“公寓”说 apartment(英式 flat);本课已按美语写。","mark":"trash/flashlight"},{"rule":"被动语态时态变化都在 be 上,过去分词不变:was done / is being done / has been done / will be done。laugh at = 嘲笑(取笑某人某事),laugh = 单纯地笑。","mark":"be + 过去分词"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l82',1,NULL,'Last week, a strange old object was found in the attic of an old house. It was covered in dust and had been forgotten for over a hundred years.','上周,在一座老房子的阁楼里发现了一件古怪的旧物。它落满灰尘,已被遗忘了一百多年。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l82',2,NULL,'At first the family laughed at it, thinking it was junk. But when it was cleaned, a curious pattern was discovered underneath.','起初,一家人还嘲笑它,以为是废物。可当把它清理干净后,底下露出一个奇特的图案。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l82',3,NULL,'Now the object is being examined by experts at the city museum. "Things like this have been seen only a few times before," one expert said.','如今,这件物品正由城里博物馆的专家们鉴定。“这样的东西以前只被见过几次,”一位专家说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l82',4,NULL,'"It is carefully studied before anyone can say what it is." Every valuable piece is kept in a special room and is checked daily.','“得先仔细研究,才能说清它是什么。”每一件珍贵的物品都被保存在一个专门的房间里,每天都有人检查。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l82',5,NULL,'Next month, the mysterious object will be shown to the public for the first time. The family who once laughed at it are now proud that it will be displayed in a museum.','下个月,这件神秘的物品将第一次向公众展出。那家曾经嘲笑它的人,如今为它将在博物馆展出而感到自豪。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
